export const SPOTTING_HOAXES_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu hoaks",q:"'Hoaks' adalah...",options:["Informasi palsu atau menyesatkan yang dibuat terlihat seperti fakta","Berita yang benar dan sudah diperiksa, tapi gayanya kurang menarik","Seluruh berita yang beredar di internet, baik yang benar maupun yang salah"],answer:0,explain:"Hoaks sengaja atau tidak sengaja menyesatkan orang untuk percaya sesuatu yang tidak benar atau menyimpang dari fakta.",hint:"Info palsu yang terlihat seperti fakta, atau berita yang tidak menarik?"},
{n:2,type:"mcq",micro:"Misinformasi vs disinformasi",q:"Beda 'misinformasi' & 'disinformasi':",options:["Misinformasi disengaja, sedangkan disinformasi tidak disengaja oleh penyebarnya","Misinformasi disebarkan tanpa sadar itu salah; disinformasi sengaja dibuat & disebar untuk menyesatkan","Keduanya sama persis, hanya beda istilah dan tidak ada bedanya dalam niat penyebarnya atau dampaknya"],answer:1,explain:"Niat membedakannya: seseorang yang membagikan info salah karena mengira benar (misinformasi) berbeda dari yang sengaja membuat kebohongan (disinformasi).",hint:"Beda niat, sengaja vs tidak, atau sama persis?"},
{n:3,type:"mcq",micro:"Kenapa hoaks menyebar cepat",q:"Hoaks sering menyebar lebih cepat daripada koreksi/fakta karena...",options:["Hoaks ditulis lebih rapi dan meyakinkan daripada fakta, sehingga lebih dulu dipercaya orang","Orang biasanya memeriksa fakta dulu sebelum membagikan, sehingga koreksi tersebar secepat hoaks","Kontennya sering mengejutkan/emosional sehingga orang cepat membagikan tanpa memeriksa dulu"],answer:2,explain:"Rasa kaget, marah, atau takut membuat orang membagikan dengan cepat, seringkali sebelum berpikir untuk memverifikasi.",hint:"Memicu emosi & dibagikan cepat, atau selalu lebih rapi?"},
{n:4,type:"mcq",micro:"Ciri umum hoaks",q:"Tanda-tanda umum yang sering muncul pada hoaks:",options:["Judul berlebihan (SEMUA HURUF BESAR/tanda seru banyak), tidak menyebut sumber jelas, & mendesak untuk segera dibagikan","Ditulis dengan nada tenang, memakai huruf biasa, dan menyebut sumber yang jelas serta bisa dicek orang","Berasal dari media besar yang tepercaya dan sudah lama dikenal, dengan alamat situs yang resmi"],answer:0,explain:"Bahasa berlebihan, sumber kabur, & desakan 'sebarkan sekarang!' adalah pola klasik konten menyesatkan.",hint:"Judul berlebihan & sumber kabur, atau tenang & bersumber jelas?"},
{n:5,type:"mcq",micro:"Judul clickbait",q:"'Judul umpan klik' (clickbait) adalah judul yang...",options:["Ditulis membosankan dan datar agar orang malas membacanya sampai selesai di halaman","Dibuat sangat menggoda/mengejutkan agar orang mengklik, meski isinya sering tidak sesuai janji judul","Menjelaskan isi berita dengan tepat dan jujur sehingga pembaca tidak kecewa setelah mengkliknya"],answer:1,explain:"'Kamu Tidak Akan Percaya Apa yang Terjadi Selanjutnya!' sering hanya trik menarik klik, isinya biasa saja.",hint:"Menggoda tapi sering tak sesuai isi, atau selalu tepat jelaskan isi?"},
{n:6,type:"mcq",micro:"Gambar bisa menyesatkan",q:"Sebuah foto asli tapi dipasangkan dengan keterangan yang salah tentang kapan/di mana itu terjadi adalah bentuk...",options:["Bukan hoaks, karena gambarnya asli dan tidak diedit, jadi keterangan yang menyertainya benar","Bisa dipercaya karena fotonya nyata, sehingga kapan dan di mana kejadiannya tidak perlu dicek","Konten menyesatkan lewat konteks yang salah, meski gambarnya sendiri tidak diedit"],answer:2,explain:"Foto asli bisa dipakai menyesatkan hanya dengan mengganti keterangan/konteksnya, tanpa perlu mengedit gambarnya sama sekali.",hint:"Konteks salah pada gambar asli, atau bukan hoaks karena asli?"},
{n:7,type:"mcq",micro:"Satire",q:"'Satire' (sindiran humor) adalah konten yang...",options:["Sengaja dibuat lucu/berlebihan untuk menyindir, tapi kadang disalahpahami sebagai berita sungguhan","Bermaksud menipu orang dengan serius agar percaya bahwa kejadiannya benar-benar terjadi","Sama persis dengan berita resmi yang disampaikan oleh media tepercaya, hanya ditulis dengan gaya yang lebih santai"],answer:0,explain:"Situs satire membuat 'berita' konyol untuk lucu-lucuan atau kritik. Masalahnya muncul saat orang membagikannya sebagai fakta sungguhan.",hint:"Sindiran humor yang kadang disalahpahami, atau selalu menipu?"},
{n:8,type:"mcq",micro:"Kenapa memeriksa fakta penting",q:"Kenapa penting memeriksa kebenaran sebelum mempercayai/membagikan sesuatu?",options:["Hanya penting bagi jurnalis dan wartawan yang bekerja di media, sedangkan pembaca biasa tidak perlu memeriksa","Informasi yang salah bisa membuat keputusan buruk, menyebarkan ketakutan, atau merugikan orang lain","Tidak penting, karena semua informasi di internet benar dan sudah diperiksa pihak berwenang"],answer:1,explain:"Keputusan (kesehatan, uang, hubungan) yang dibuat berdasar info salah bisa berakibat nyata & merugikan.",hint:"Mencegah keputusan buruk & kerugian, atau tak penting?"},
{n:9,type:"order",micro:"Alur sebuah hoaks menyebar",q:"Urutkan bagaimana hoaks biasanya menyebar.",items:["Seseorang membuat/menemukan info yang menarik perhatian & mengejutkan","Info dibagikan cepat karena reaksi emosional, tanpa diperiksa dulu","Semakin banyak dibagikan, semakin terlihat 'pasti benar' karena banyak yang percaya","Butuh usaha lebih untuk koreksi menjangkau orang yang sama, & koreksi sering kalah cepat"],answer:[0,1,2,3],explain:"Buat/temukan → bagikan cepat tanpa cek → terlihat kredibel karena banyak dibagikan → koreksi tertinggal. Memahami alur ini membantu kita berhenti di langkah kedua.",hint:"Info terlihat 'pasti benar' karena banyak dibagikan sebelum atau sesudah koreksi datang?"},
{n:10,type:"mcq",micro:"Jeda sebelum membagikan",q:"Kebiasaan sederhana yang paling berguna melawan penyebaran hoaks:",options:["Membagikan secepat mungkin agar orang lain tahu duluan, karena yang pertama membagikan dianggap paling berjasa","Hanya membaca judulnya lalu langsung percaya dan membagikan, karena judul biasanya sudah mewakili seluruh isi beritanya","Berhenti sejenak & bertanya 'apakah ini benar?' sebelum membagikan, bukan langsung membagikan karena terlihat menarik"],answer:2,explain:"Jeda sederhana ini adalah pertahanan pertama yang paling efektif & bisa dilakukan siapa saja.",hint:"Jeda & tanya dulu, atau bagikan secepatnya?"},
{n:11,type:"tf",micro:"Semua yang viral pasti benar?",q:"Benar atau Salah: Sebuah info yang dibagikan sangat banyak orang (viral) otomatis berarti info itu benar.",answer:false,explain:"Sebaliknya, viral hanya berarti banyak dibagikan, bukan berarti diverifikasi benar. Hoaks pun bisa viral, bahkan sering lebih cepat viral daripada berita akurat.",hint:"Viral = pasti benar, atau viral tidak menjamin kebenaran?"},
{n:12,type:"tf",micro:"Niat baik bisa menyebarkan hoaks",q:"Benar atau Salah: Seseorang bisa menyebarkan info salah dengan niat baik (ingin membantu/memperingatkan), tanpa bermaksud menipu.",answer:true,explain:"Ini disebut misinformasi. Orang tua yang membagikan info kesehatan palsu 'demi keamanan anak' sering melakukannya dengan niat baik tapi tetap menyebarkan yang salah.",hint:"Bisa disebar dengan niat baik, atau selalu sengaja menipu?"},
{n:13,type:"mcq",micro:"Reaksi emosional sebagai jebakan",q:"Konten yang membuatmu langsung marah, takut, atau sangat gembira sebelum sempat berpikir sebaiknya...",options:["Justru jadi tanda untuk lebih berhati-hati & memeriksa dulu, karena emosi kuat sering dipakai untuk melewati pikiran kritis","Langsung dipercaya karena terasa nyata dan menyentuh perasaan, sehingga tidak perlu diperiksa kebenarannya lagi","Diabaikan tanpa dibaca, karena semua konten yang memancing emosi bohong dan tidak berguna"],answer:0,explain:"Pembuat konten menyesatkan sering sengaja memancing emosi kuat karena itu membuat orang lupa memeriksa fakta.",hint:"Tanda untuk lebih hati-hati, atau langsung percaya karena terasa nyata?"},
{n:14,type:"mcq",micro:"Sumber tanpa nama",q:"Info yang hanya menyebut 'menurut sumber yang tidak mau disebutkan' atau 'kabarnya' tanpa bukti lebih jauh...",options:["Hoaks, karena kabar dari sumber yang tidak disebutkan tidak mungkin benar","Perlu diperiksa lebih dulu ke sumber yang bisa diverifikasi sebelum dipercaya penuh","Bisa dipercaya karena terdengar rahasia dan penting, sehingga tak perlu dicek lagi ke sumber lain"],answer:1,explain:"Sumber yang kabur bukan otomatis salah, tapi butuh verifikasi tambahan sebelum dianggap fakta.",hint:"Perlu diperiksa lebih lanjut, atau langsung percaya / langsung tolak?"},
{n:15,type:"mcq",micro:"Angka & statistik menyesatkan",q:"Klaim '9 dari 10 orang setuju...' tanpa menyebut siapa yang disurvei atau berapa jumlah orangnya patut dicurigai karena...",options:["Statistik akurat, karena angka berasal dari perhitungan dan tidak mungkin dibuat menyesatkan orang","Angka yang besar berarti benar, sehingga makin besar angkanya makin kuat bukti bahwa klaimnya tepat","Angka tanpa konteks (jumlah responden, cara survei) bisa dibuat terlihat meyakinkan padahal tidak mewakili"],answer:2,explain:"Statistik yang tidak menyebut metodenya bisa dimanipulasi atau tidak mewakili kenyataan yang lebih luas.",hint:"Perlu konteks, atau angka besar selalu benar?"},
{n:16,type:"tf",micro:"Semua orang bisa terkena hoaks",q:"Benar atau Salah: Hanya orang yang kurang pintar atau kurang berpendidikan yang bisa tertipu hoaks; orang pintar tidak mungkin tertipu.",answer:false,explain:"Sebaliknya, tertipu hoaks bukan soal kurang pintar, tapi soal kebiasaan memeriksa. Siapa pun, termasuk orang berpendidikan, bisa tertipu hoaks yang dirancang meyakinkan, apalagi di luar bidang keahliannya.",hint:"Siapa saja bisa tertipu, atau hanya orang tertentu?"},
{n:17,type:"mcq",micro:"Gambar/video buatan (deepfake sederhana)",q:"Teknologi kini bisa membuat video/suara palsu yang terlihat/terdengar sangat nyata (deepfake). Ini berarti...",options:["Melihat/mendengar sesuatu tidak lagi otomatis cukup untuk 'membuktikan' kebenarannya; verifikasi tambahan makin penting","Semua video tetap bisa dipercaya penuh karena kamera tidak berbohong, apa yang direkamnya itu nyata","Teknologi ini dipakai untuk hiburan dan keperluan baik, sehingga tidak dipakai untuk menyesatkan orang lain"],answer:0,explain:"Kemajuan teknologi membuat verifikasi silang (sumber lain, konteks) makin penting, bukan makin tidak perlu.",hint:"Verifikasi makin penting, atau kamera pasti tidak berbohong?"},
{n:18,type:"mcq",micro:"Judul vs isi",q:"Kebiasaan hanya membaca judul lalu langsung membagikan berisiko karena...",options:["Isi artikel tidak penting karena pesan utama sudah tertulis lengkap di judulnya sendiri","Judul kadang tidak mewakili isi sebenarnya, atau bahkan bertentangan dengan isi artikel","Judul sama dengan isi artikel, sehingga membaca judulnya saja cukup untuk memahami semuanya"],answer:1,explain:"Banyak orang membagikan hanya berdasarkan judul tanpa membaca isi, yang bisa menyebarkan kesan yang keliru.",hint:"Judul bisa tidak mewakili isi, atau selalu sama persis?"},
{n:19,type:"mcq",micro:"Tanggal kadaluarsa info",q:"Sebuah berita/foto lama yang dibagikan ulang seolah baru terjadi adalah bentuk hoaks yang memanfaatkan...",options:["Gambar yang diedit secara teknis untuk menambah atau menghapus sesuatu","Hal yang jarang terjadi, karena orang enggan membagikan ulang berita atau foto lama","Konteks waktu yang salah, kejadian lama disajikan seolah baru & relevan sekarang"],answer:2,explain:"Peristiwa lama (bencana, kerusuhan) sering didaur ulang & dibagikan seolah baru terjadi untuk memicu reaksi.",hint:"Konteks waktu yang salah, atau selalu gambar diedit?"},
{n:20,type:"open",micro:"Analisis sebuah pesan viral",q:"Bayangkan kamu menerima pesan berantai: 'PENTING! Rumah sakit X kekurangan darah, semua golongan darah dibutuhkan SEKARANG, sebarkan ke semua grup sebelum jam 8 malam!' tanpa nama rumah sakit yang jelas, tanpa tanggal, & tanpa kontak resmi. Analisis: (a) 3 tanda yang membuatmu curiga, (b) 3 langkah yang akan kamu lakukan sebelum percaya/membagikan, (c) apa yang akan kamu lakukan kalau setelah dicek ternyata memang benar ada kebutuhan darah, tapi pesannya sendiri tidak akurat (rumah sakitnya salah/sudah lama).",explain:"Jawaban baik: 3 tanda kecurigaan yang spesifik (bukan nama jelas, urgensi berlebihan, tanpa kontak resmi/format pesan berantai lama), 3 langkah verifikasi yang konkret & bisa dilakukan (cari berita, cek sumber resmi, konfirmasi langsung), & respons matang untuk skenario 'sebagian benar sebagian salah', membagikan info yang benar & terbaru, bukan meneruskan yang keliru begitu saja.",hint:"Untuk (c), ingat bahwa niat baik (ingin membantu) tidak menghapus tanggung jawab menyebarkan info yang akurat.",sample:"(a) Tanda kecurigaan: (1) Tidak menyebut nama rumah sakit dengan jelas & lengkap, sulit diverifikasi. (2) Ada tenggat waktu mendesak ('sebelum jam 8 malam') yang mendorong panik & buru-buru menyebarkan tanpa cek. (3) Tidak ada kontak resmi (nomor telepon PMI/rumah sakit) untuk konfirmasi langsung; pesan seperti ini juga terasa seperti format pesan berantai yang sudah lama beredar berulang kali dengan detail berubah-ubah. (b) Langkah sebelum percaya: (1) Cari nama rumah sakit itu di internet bersama kata 'kekurangan darah' untuk melihat apakah ada berita resmi terbaru. (2) Cek situs/media sosial resmi PMI (Palang Merah Indonesia) setempat untuk info kebutuhan darah yang biasanya diperbarui rutin & jelas sumbernya. (3) Kalau ada nomor kontak, coba hubungi langsung untuk konfirmasi, bukan hanya percaya teks yang diteruskan. (c) Kalau memang ada kebutuhan nyata tapi detail pesannya salah/lama: aku akan mencari & membagikan info yang benar & terbaru dari sumber resmi (mis. akun PMI setempat), bukan meneruskan pesan lama yang salah, karena info yang sudah usang bisa membuat orang datang ke tempat yang keliru & justru tidak membantu kebutuhan yang sebenarnya."},
{n:21,type:"classify",micro:"Tanda hoaks vs tanda info tepercaya",q:"Kelompokkan tiap tanda ke 'Cenderung hoaks/menyesatkan' atau 'Cenderung info tepercaya'.",items:["Judul 'SADIS!!! Kamu Wajib Tahu Sebelum Terlambat!!!'","Menyebut nama penulis, tanggal, & sumber data yang jelas","Mendesak 'sebarkan sebelum dihapus!'","Ada rujukan ke laporan resmi/lembaga yang bisa dicek"],groups:["Cenderung hoaks/menyesatkan","Cenderung info tepercaya"],answer:{"Cenderung hoaks/menyesatkan":["Judul 'SADIS!!! Kamu Wajib Tahu Sebelum Terlambat!!!'","Mendesak 'sebarkan sebelum dihapus!'"],"Cenderung info tepercaya":["Menyebut nama penulis, tanggal, & sumber data yang jelas","Ada rujukan ke laporan resmi/lembaga yang bisa dicek"]},explain:"Hoaks: bahasa berlebihan, mendesak. Tepercaya: identitas jelas, bisa dirujuk & diperiksa.",hint:"Bahasa berlebihan & mendesak, atau identitas jelas & bisa dicek?"},
{n:22,type:"mcq",micro:"Konten yang diedit (manipulasi gambar)",q:"Gambar yang telah diedit untuk menambah/menghapus sesuatu (mis. menambahkan orang yang tidak ada) berbeda dari konten 'konteks salah' karena...",options:["Gambar itu sendiri sudah diubah secara teknis, bukan hanya keterangannya yang salah","Keduanya sama, hanya beda istilah, tanpa perbedaan dari segi cara kerja","Gambar yang diedit lebih mudah dikenali daripada konteks yang salah, sehingga jarang ada yang tertipu"],answer:0,explain:"Ada beberapa jenis manipulasi: mengedit gambar/video (teknis) & mengganti konteks/keterangan (tanpa mengedit media). Keduanya menyesatkan dengan cara berbeda.",hint:"Media itu sendiri diubah, atau hanya keterangannya?"},
{n:23,type:"mcq",micro:"Konten setengah benar",q:"Konten yang paling sulit dikenali sebagai menyesatkan sering yang...",options:["Ditulis dengan bahasa yang sangat kaku dan membosankan, sehingga justru terlihat paling bisa dipercaya oleh pembacanya","Sebagian faktanya benar, tapi disusun/ditambah sedikit hal salah sehingga kesimpulannya menyesatkan","Seluruhnya jelas bohong dari awal sampai akhir, sehingga langsung dikenali dalam sekali baca"],answer:1,explain:"Kebohongan yang dibungkus fakta asli lebih sulit dikenali & lebih meyakinkan daripada kebohongan total.",hint:"Sebagian benar dicampur sedikit salah, atau seluruhnya jelas bohong?"},
{n:24,type:"mcq",micro:"Akun/situs peniru",q:"Sebuah akun bernama mirip media besar tapi dengan sedikit perbedaan ejaan (mis. 'BBC-News-Update' bukan akun resmi BBC) adalah taktik...",options:["Cara resmi yang dipakai media besar untuk membuat akun cadangan ketika akun utama mereka mengalami gangguan teknis","Jelas terlihat sebagai parodi atau lelucon, sehingga tak ada orang yang mungkin menganggapnya akun resmi","Meniru kredibilitas nama besar untuk membuat kontennya terlihat tepercaya padahal bukan sumber aslinya"],answer:2,explain:"Nama yang mirip tapi tidak identik sengaja dipakai untuk 'meminjam' kepercayaan pada nama besar tanpa benar-benar menjadi bagian darinya.",hint:"Meniru kredibilitas nama besar, atau cara resmi media?"},
{n:25,type:"mcq",micro:"Klaim kesehatan tanpa bukti",q:"Klaim 'ramuan X sembuhkan segala penyakit dalam semalam' tanpa penelitian yang bisa dicek patut dicurigai karena...",options:["Klaim kesehatan yang sangat besar biasanya butuh bukti ilmiah kuat; klaim ajaib tanpa bukti sering menyesatkan & bisa berbahaya","Ramuan tradisional bohong dan tidak mungkin punya manfaat, tanpa perlu diteliti lebih lanjut","Klaim besar yang terdengar hebat terbukti benar, sehingga makin ajaib klaimnya makin besar pula kebenarannya"],answer:0,explain:"Semakin besar klaimnya (menyembuhkan 'segala penyakit'), semakin besar bukti yang seharusnya menyertainya. Ketiadaan bukti adalah tanda bahaya.",hint:"Klaim besar butuh bukti kuat, atau pasti benar / pasti bohong?"},
{n:26,type:"mcq",micro:"Teori konspirasi",q:"Ciri umum 'teori konspirasi' yang perlu diwaspadai:",options:["Mudah diverifikasi dengan cepat lewat sumber resmi, dan sanggahan yang disertai bukti diterima dengan terbuka oleh para penganutnya","Mengklaim kebenaran disembunyikan pihak berkuasa, sulit dibantah dengan bukti apa pun (semua sanggahan dianggap 'bagian dari konspirasi')","Didukung banyak bukti ilmiah yang kuat dan diterima para ahli, sehingga tak ada yang menganggapnya aneh"],answer:1,explain:"Ciri khasnya: 'kebal' terhadap bukti, karena bukti yang membantahnya justru dianggap bukti konspirasi makin dalam.",hint:"Kebal terhadap bukti & sulit dibantah, atau didukung bukti kuat?"},
{n:27,type:"tf",micro:"Screenshot bisa dipalsukan",q:"Benar atau Salah: Tangkapan layar (screenshot) percakapan atau postingan selalu jadi bukti pasti bahwa sesuatu benar-benar terjadi persis seperti itu.",answer:false,explain:"Sebaliknya, alat pengedit gambar bisa membuat screenshot palsu terlihat sangat meyakinkan. Verifikasi dari sumber asli tetap penting sebelum menganggapnya bukti pasti.",hint:"Bisa dipalsukan, atau selalu bukti pasti?"},
{n:28,type:"tf",micro:"Sumber anonim selalu salah?",q:"Benar atau Salah: Informasi dari sumber yang identitasnya tidak disebutkan pasti selalu salah/hoaks.",answer:false,explain:"Sebaliknya, tidak selalu, kadang ada alasan sah menyembunyikan identitas sumber (mis. melindungi keselamatan). Tapi info seperti ini memang butuh verifikasi ekstra sebelum dipercaya penuh.",hint:"Pasti salah, atau bisa jadi sah tapi tetap butuh verifikasi ekstra?"},
{n:29,type:"mcq",micro:"Emosi & bagikan cepat",q:"Studi menunjukkan konten yang memicu kemarahan/kejutan cenderung dibagikan lebih cepat & lebih jauh daripada konten netral karena...",options:["Konten emosional lebih akurat dari konten netral","Orang membagikan konten yang datar dan membosankan, sehingga konten pemicu emosi cepat dilupakan","Emosi kuat mendorong tindakan cepat (membagikan) sebelum berpikir panjang"],answer:2,explain:"Memahami pola ini membantu kita sadar: kalau kita merasa sangat emosional saat membaca sesuatu, itu saat yang tepat untuk melambat, bukan mempercepat.",hint:"Emosi mendorong tindakan cepat, atau konten emosional selalu akurat?"},
{n:30,type:"order",micro:"Mengenali pola manipulasi",q:"Urutkan langkah menganalisis sebuah gambar yang mencurigakan.",items:["Perhatikan apakah ada bagian yang terlihat aneh (bayangan tidak konsisten, tepi kabur)","Cek apakah keterangan/konteksnya sesuai dengan yang terlihat di gambar","Cari apakah gambar yang sama pernah muncul dengan keterangan berbeda di masa lalu","Simpulkan tingkat kepercayaanmu berdasarkan semua temuan itu"],answer:[0,1,2,3],explain:"Periksa gambar itu sendiri → cocokkan dengan keterangan → cek riwayat pemakaian gambar → simpulkan. Kesimpulan datang setelah semua bukti terkumpul.",hint:"Menyimpulkan di awal atau setelah mengumpulkan semua temuan?"},
{n:31,type:"mcq",micro:"Bias konfirmasi & hoaks",q:"'Bias konfirmasi' membuat kita lebih mudah percaya hoaks yang...",options:["Sesuai dengan apa yang sudah kita yakini atau inginkan, sehingga kita tidak memeriksanya sekritis biasa","Bertentangan dengan pandangan kita, sehingga kita lebih mudah percaya pada sesuatu yang berlawanan dengan keyakinan sendiri","Netral dan tidak terkait dengan pandangan kita, sehingga kita memeriksanya sama kritisnya seperti info lain"],answer:0,explain:"Kita cenderung kurang skeptis pada info yang 'mengonfirmasi' apa yang sudah kita percaya, meski itu sama tidak berdasarnya dengan info yang kita ragukan.",hint:"Sesuai keyakinan kita sendiri, atau bertentangan dengan pandangan kita?"},
{n:32,type:"tf",micro:"Media resmi bisa salah juga",q:"Benar atau Salah: Media berita resmi tidak pernah membuat kesalahan, jadi begitu sumbernya tepercaya, tidak perlu bersikap kritis sama sekali.",answer:false,explain:"Sebaliknya, bahkan media berita resmi kadang membuat kesalahan atau perlu mengoreksi beritanya, jadi tetap baik bersikap sedikit kritis meski dari sumber tepercaya. Kredibilitas mengurangi risiko, bukan menghapusnya.",hint:"Bisa salah juga, atau selalu 100% benar?"},
{n:33,type:"mcq",micro:"Video dipotong tanpa konteks",q:"Sebuah video pendek yang dipotong dari video lebih panjang bisa menyesatkan karena...",options:["Memotong video tidak mengubah makna aslinya, asal gambar dan suaranya tak diedit","Kehilangan konteks sebelum & sesudahnya bisa mengubah makna kejadian yang sebenarnya","Video pendek lebih akurat daripada video panjang, karena hanya menampilkan bagian terpenting saja"],answer:1,explain:"Potongan 10 detik dari percakapan 10 menit bisa membalikkan makna aslinya. Mencari video/konteks lengkap penting sebelum menyimpulkan.",hint:"Kehilangan konteks bisa mengubah makna, atau selalu lebih akurat?"},
{n:34,type:"mcq",micro:"Klaim 'ilmuwan mengatakan' tanpa nama",q:"Klaim 'para ilmuwan menemukan...' tanpa menyebut ilmuwan mana, penelitian mana, atau di mana dipublikasikan...",options:["Otomatis benar karena menyebut kata 'ilmuwan', sehingga tak perlu dicari tahu siapa dan di mana dipublikasikan","Berarti penelitian itu tidak ada, karena klaim yang menyebut ilmuwan tanpa nama bohong","Sulit diverifikasi & patut diperlakukan dengan hati-hati sampai ada rincian yang bisa dicek"],answer:2,explain:"Kata 'ilmuwan' atau 'penelitian menunjukkan' tanpa rincian yang bisa dilacak adalah tanda perlu verifikasi lebih jauh.",hint:"Perlu verifikasi rincian, atau otomatis benar karena kata 'ilmuwan'?"},
{n:35,type:"mcq",micro:"Foto profil & akun palsu",q:"Akun dengan foto profil yang terlihat sangat sempurna/seperti model, sedikit pengikut, & baru dibuat, yang menyebarkan klaim mengejutkan, patut...",options:["Diperiksa lebih dulu keasliannya sebelum dipercaya, ini pola umum akun palsu/bot","Dipercaya begitu saja karena fotonya menarik, dan akun seperti itu dimiliki orang asli yang jujur","Diabaikan sebagai lelucon, karena akun palsu dan bot jarang ada di media sosial"],answer:0,explain:"Kombinasi akun baru, sedikit jejak aktivitas nyata, & klaim besar adalah kombinasi yang layak dicurigai.",hint:"Diperiksa dulu keasliannya, atau langsung percaya / abaikan tanpa pikir?"},
{n:36,type:"mcq",micro:"Perbandingan sumber",q:"Kalau hanya SATU sumber yang memberitakan sesuatu yang besar & mengejutkan, sementara sumber lain tidak menyebutnya sama sekali, itu tanda untuk...",options:["Menganggap sumber lain menyembunyikannya, sehingga satu sumber itu yang paling berani","Lebih berhati-hati; berita besar yang benar biasanya diliput banyak sumber, bukan hanya satu","Langsung percaya karena itu eksklusif dan hanya ada di satu sumber, sehingga tidak perlu dicek ke sumber lain"],answer:1,explain:"Berita besar yang benar biasanya terverifikasi & diliput banyak pihak. Keunikan ekstrem (hanya satu sumber) patut menimbulkan kehati-hatian.",hint:"Lebih berhati-hati, atau langsung percaya / curigai sumber lain?"},
{n:37,type:"tf",micro:"Hoaks bisa berbentuk lelucon yang lolos",q:"Benar atau Salah: Konten satire/lelucon selalu jelas terlihat sebagai lelucon oleh siapa pun yang membacanya, tidak mungkin disalahpahami sebagai fakta.",answer:false,explain:"Sebaliknya, ini masalah umum: lelucon yang dilepas dari konteks 'ini satire' oleh orang yang membagikan ulang bisa berubah jadi info yang dipercaya sungguhan.",hint:"Bisa tersebar seolah fakta, atau selalu jelas sebagai lelucon?"},
{n:38,type:"mcq",micro:"Klaim ekstrem tanpa bukti proporsional",q:"Prinsip umum: klaim yang sangat luar biasa membutuhkan...",options:["Bukti yang lebih sedikit daripada klaim biasa, karena klaim luar biasa sudah terbukti dengan sendirinya","Tidak butuh bukti karena klaimnya sudah jelas luar biasa, sehingga orang langsung percaya padanya","Bukti yang sangat kuat & jelas, bukan sekadar cerita atau screenshot tanpa asal-usul"],answer:2,explain:"Semakin besar & mengejutkan klaimnya, semakin besar pula standar bukti yang seharusnya menyertainya sebelum dipercaya.",hint:"Butuh bukti kuat, atau tak butuh bukti karena luar biasa?"},
{n:39,type:"mcq",micro:"Perbedaan opini & fakta yang salah",q:"Membedakan 'aku tidak setuju dengan pendapat ini' dengan 'ini secara faktual salah' penting karena...",options:["Opini bisa berbeda-beda secara sah; fakta yang salah adalah soal ketepatan yang bisa diperiksa, keduanya butuh sikap berbeda","Keduanya sama saja dan harus ditanggapi dengan cara yang sama, yaitu dengan menolak orang yang berpendapat berbeda","Opini lebih penting daripada fakta, sehingga perbedaan pendapat harus dimenangkan yang paling keras"],answer:0,explain:"Kita bisa menghargai perbedaan opini sambil tetap tegas soal fakta yang keliru. Mencampur keduanya membuat diskusi kacau.",hint:"Beda sikap untuk opini & fakta salah, atau perlakukan sama?"},
{n:40,type:"open",micro:"Bedakan opini, fakta, & klaim salah",q:"Baca tiga pernyataan berikut & klasifikasikan masing-masing sebagai 'Fakta yang bisa diperiksa', 'Opini', atau 'Klaim yang perlu diverifikasi lebih lanjut', lalu jelaskan alasanmu: (1) 'Air mendidih pada 100°C di permukaan laut.' (2) 'Film itu adalah film terbaik tahun ini.' (3) 'Minum air lemon tiap pagi bisa menyembuhkan semua penyakit dalam seminggu.'",explain:"Jawaban baik: klasifikasi yang tepat untuk ketiganya, penjelasan yang menunjukkan pemahaman kenapa (1) bisa diukur objektif, (2) soal selera tanpa jawaban tunggal benar, & (3) klaim besar tanpa bukti proporsional yang patut dicurigai & bisa berbahaya.",hint:"Fakta = bisa diukur/dibuktikan objektif. Opini = soal selera/penilaian pribadi. Klaim mencurigakan = besar, tanpa bukti, sering soal kesehatan/uang.",sample:"(1) 'Air mendidih pada 100°C di permukaan laut': FAKTA yang bisa diperiksa. Ini adalah hukum fisika dasar yang bisa diuji & diukur secara konsisten, tidak bergantung pada pendapat siapa pun, & sudah diverifikasi berulang kali oleh sains. (2) 'Film itu adalah film terbaik tahun ini': OPINI. Ini soal selera & penilaian pribadi, orang bisa punya kriteria berbeda (cerita, akting, visual) & menilai secara berbeda pula; tidak ada satu jawaban benar yang bisa 'dibuktikan' secara objektif. (3) 'Minum air lemon tiap pagi bisa menyembuhkan semua penyakit dalam seminggu': KLAIM YANG PERLU DIVERIFIKASI LEBIH LANJUT, & sangat mencurigakan. Ini klaim kesehatan yang sangat besar ('semua penyakit', 'seminggu') tanpa menyebut penelitian atau bukti ilmiah apa pun; klaim sebesar ini butuh bukti kuat yang bisa dicek, & ketiadaannya adalah tanda bahaya besar bahwa ini kemungkinan menyesatkan atau bahkan berbahaya jika membuat orang menunda pengobatan yang sebenarnya diperlukan."},
{n:41,type:"mcq",micro:"Lateral reading",q:"'Membaca lateral' (lateral reading) berarti...",options:["Membaca judul saja lalu berhenti, karena judul sudah cukup untuk menilai kredibilitas sebuah situs atau klaim","Membuka tab/sumber lain untuk mengecek kredibilitas sebuah situs/klaim, bukan hanya membaca situs itu sendiri lebih dalam","Membaca dari kiri ke kanan seperti biasa pada satu situs yang sama, sampai semua halamannya selesai dibaca"],answer:1,explain:"Alih-alih tenggelam membaca satu situs, ahli pemeriksa fakta cepat membuka tab baru untuk mencari 'siapa sebenarnya situs ini?' dari sumber luar.",hint:"Cek dari sumber lain, atau membaca dalam satu situs lebih dalam?"},
{n:42,type:"mcq",micro:"Mencari sumber lain",q:"Langkah dasar memverifikasi klaim mengejutkan:",options:["Percaya begitu satu sumber menyebutkannya, apalagi bila terlihat meyakinkan","Tanya teman-temanmu apakah mereka juga percaya, dan kalau mereka percaya maka klaim itu benar","Cari apakah media/sumber tepercaya lain juga melaporkan hal yang sama"],answer:2,explain:"Klaim yang benar & penting biasanya bisa dikonfirmasi dari lebih dari satu sumber yang independen satu sama lain.",hint:"Cek sumber lain independen, atau cukup satu sumber / tanya teman?"},
{n:43,type:"mcq",micro:"Pencarian gambar terbalik",q:"'Pencarian gambar terbalik' (reverse image search) berguna untuk...",options:["Menemukan dari mana & kapan sebuah gambar pertama kali muncul, mengungkap apakah dipakai di konteks lain sebelumnya","Membalik warna sebuah gambar menjadi negatif agar detail yang tersembunyi di dalamnya terlihat lebih jelas oleh mata","Membuat gambar terbalik, atas ke bawah, agar mudah dibandingkan dengan gambar aslinya"],answer:0,explain:"Alat ini mengunggah/menempel gambar untuk mencari kemunculannya di tempat lain, mengungkap apakah gambar itu lama/dipakai di konteks berbeda.",hint:"Menemukan asal & riwayat gambar, atau membalik warnanya?"},
{n:44,type:"mcq",micro:"Memeriksa tanggal",q:"Sebelum mempercayai sebuah 'berita', memeriksa tanggal publikasinya penting karena...",options:["Semua berita otomatis diperbarui sendiri oleh situs, sehingga tanggal terbit tidak jadi masalah bagi pembaca","Berita lama yang dibagikan ulang seolah baru bisa memberi kesan yang salah tentang situasi saat ini","Tanggal tidak relevan dengan kebenaran, sebab berita yang benar tetap benar kapan pun dibagikan"],answer:1,explain:"Info yang benar pada waktunya bisa jadi tidak relevan atau menyesatkan bila dibagikan ulang seolah menggambarkan situasi sekarang.",hint:"Tanggal lama bisa menyesatkan, atau tidak relevan?"},
{n:45,type:"tf",micro:"Mengecek 'Tentang Kami' situs",q:"Benar atau Salah: Halaman 'Tentang Kami' & identitas penulis sebuah situs tidak ada gunanya sama sekali untuk menilai kredibilitasnya.",answer:false,explain:"Sebaliknya, memeriksa halaman 'Tentang Kami' & siapa penulisnya bisa membantu menilai kredibilitas situs, meski tidak selalu cukup sendirian. Situs yang jelas menyebut pemilik & kontaknya lebih mudah diverifikasi daripada yang anonim sepenuhnya.",hint:"Membantu menilai kredibilitas, atau tak berguna sama sekali?"},
{n:46,type:"mcq",micro:"Mengecek organisasi pemeriksa fakta",q:"Organisasi pemeriksa fakta (fact-checker) independen berguna karena...",options:["Mereka bias dan tidak bisa dipercaya, sehingga hasil pemeriksaan mereka lebih baik diabaikan","Hanya ada satu organisasi seperti itu di seluruh dunia, sehingga hasilnya sulit dibandingkan dan dicek","Mereka meneliti klaim viral secara khusus & menerbitkan hasil verifikasinya, bisa jadi rujukan cepat"],answer:2,explain:"Mencari nama klaim + kata 'cek fakta' sering langsung menemukan apakah klaim itu sudah diperiksa sebelumnya.",hint:"Rujukan verifikasi cepat, atau selalu bias?"},
{n:47,type:"mcq",micro:"Mengecek angka dengan sumber resminya",q:"Klaim statistik ('jumlah kasus naik 500%!') sebaiknya dicek dengan...",options:["Mencari data resmi dari lembaga terkait (pemerintah, penelitian) untuk membandingkan angka aslinya","Percaya begitu saja karena angkanya terdengar dramatis dan meyakinkan, sehingga tidak perlu mencari data pembandingnya","Menghitung ulang sendiri dari ingatan tanpa data, lalu membandingkannya dengan angka yang beredar"],answer:0,explain:"Statistik bisa dipelintir (memilih rentang waktu tertentu, membandingkan angka yang tidak setara). Data resmi memberi gambaran yang lebih lengkap.",hint:"Bandingkan dengan data resmi, atau percaya karena dramatis?"},
{n:48,type:"mcq",micro:"Mengenali gambar yang diedit",q:"Tanda gambar mungkin telah diedit secara digital:",options:["Resolusi yang tinggi dan ukuran file yang besar sehingga gambar mudah dibagikan ke banyak orang","Bayangan yang tidak konsisten arahnya, tepi objek yang kabur/aneh, atau proporsi yang tidak wajar","Warna yang cerah dan kontras yang kuat sehingga gambar tampak menarik"],answer:1,explain:"Ketidakkonsistenan fisik (cahaya, bayangan, proporsi) sering jadi petunjuk manipulasi, meski tidak selalu mudah terlihat.",hint:"Ketidakkonsistenan bayangan/tepi/proporsi, atau warna cerah?"},
{n:49,type:"mcq",micro:"Verifikasi klaim yang menyangkut dirimu sendiri",q:"Kalau kamu mendengar kabar tentang sesuatu yang sangat dekat dengan hidupmu (sekolah, keluarga, tempat tinggal), langkah verifikasi terbaik:",options:["Percaya saja karena sumbernya adalah orang yang kamu kenal dan percaya, tanpa perlu bertanya ke pihak yang terlibat","Sebarkan dulu ke keluarga dan teman-teman supaya mereka waspada, baru kemudian memeriksa kebenarannya belakangan","Tanyakan langsung ke pihak yang berwenang/terlibat (mis. pihak sekolah), bukan hanya percaya rantai kabar dari mulut ke mulut"],answer:2,explain:"Kabar dari mulut ke mulut sering berubah tiap diteruskan (seperti permainan bisik berantai). Sumber langsung lebih akurat.",hint:"Tanya langsung ke pihak berwenang, atau percaya rantai kabar?"},
{n:50,type:"order",micro:"Proses verifikasi cepat",q:"Urutkan langkah verifikasi cepat sebuah klaim yang kamu temui.",items:["Perhatikan reaksimu; kalau sangat emosional, jeda sejenak","Cari nama/inti klaimnya di mesin pencari untuk lihat sumber lain","Periksa siapa sumber aslinya & kapan diterbitkan","Putuskan: percaya, ragukan, atau cari info lebih lanjut sebelum membagikan"],answer:[0,1,2,3],explain:"Jeda emosi → cari sumber lain → periksa asal & tanggal → putuskan. Jeda emosi adalah langkah pertama yang sering dilupakan.",hint:"Jeda karena emosi kuat dilakukan di langkah pertama atau terakhir?"},
{n:51,type:"mcq",micro:"Membedakan berita & opini di media",q:"Bagian 'opini' atau 'kolom' di media berita berbeda dari bagian 'berita' karena...",options:["Opini berisi pandangan pribadi penulis, sementara berita seharusnya melaporkan fakta yang bisa diverifikasi","Keduanya sama persis, sama-sama berisi fakta yang sudah diverifikasi, hanya diletakkan di bagian halaman yang berbeda","Opini lebih akurat daripada berita, sebab penulis opini adalah orang yang paling tahu"],answer:0,explain:"Media yang baik memisahkan keduanya dengan label jelas. Mengenali bagian mana yang sedang kamu baca membantu menilai isinya dengan tepat.",hint:"Opini = pandangan pribadi, berita = fakta terverifikasi, atau keduanya sama?"},
{n:52,type:"tf",micro:"Verifikasi butuh sedikit usaha, bukan ahli",q:"Benar atau Salah: Memverifikasi klaim viral hanya bisa dilakukan oleh jurnalis atau ahli khusus, orang biasa tidak akan mampu melakukannya.",answer:false,explain:"Sebaliknya, sebagian besar verifikasi dasar bisa dilakukan siapa saja dengan kebiasaan sederhana, seperti mencari sumber lain & memeriksa tanggal/konteks, bukan hanya oleh jurnalis atau ahli.",hint:"Bisa dilakukan siapa saja dengan kebiasaan sederhana, atau butuh keahlian khusus?"},
{n:53,type:"mcq",micro:"Mengecek konsistensi cerita",q:"Sebuah cerita viral yang detailnya berubah-ubah tiap kali diceritakan ulang (jumlah korban berubah, lokasi berubah) adalah tanda...",options:["Tak ada yang perlu dicurigai, perubahan detail itu wajar dan menunjukkan ceritanya makin lengkap","Cerita itu mungkin sedang 'diperbesar' dari mulut ke mulut & butuh dicek ke sumber asli yang stabil","Cerita itu makin dipercaya karena makin detail, sehingga makin sering berubah makin kuat kebenarannya"],answer:1,explain:"Detail yang berubah-ubah adalah tanda klasik cerita yang 'membesar' seiring penyebaran, mirip permainan bisik berantai.",hint:"Tanda cerita membesar & perlu dicek, atau makin dipercaya karena detail?"},
{n:54,type:"mcq",micro:"Memeriksa klaim 'menurut penelitian'",q:"Untuk mengecek klaim 'menurut penelitian, X menyebabkan Y', langkah yang baik:",options:["Percaya begitu saja karena klaim itu menyebut kata 'penelitian', sehingga tidak perlu mencari tahu penelitiannya lagi","Abaikan semua klaim yang menyebut penelitian, karena penelitian bisa dibuat-buat oleh siapa saja","Cari nama penelitiannya, siapa yang melakukan, & apakah diterbitkan di tempat yang bisa diperiksa"],answer:2,explain:"Kata 'penelitian' tanpa rincian yang bisa dilacak sering dipakai untuk terdengar meyakinkan tanpa dasar nyata.",hint:"Cari rincian penelitiannya, atau percaya / abaikan tanpa cek?"},
{n:55,type:"mcq",micro:"Waspada pada 'terlalu bagus untuk jadi benar'",q:"Tawaran atau klaim yang terasa 'terlalu bagus untuk jadi benar' (hadiah besar gratis, cara cepat kaya) biasanya...",options:["Memang perlu dicurigai; hal yang terdengar terlalu menguntungkan tanpa usaha sering merupakan penipuan","Benar, karena orang jarang berbohong soal hal baik, apalagi bila hadiahnya diberikan cuma-cuma","Tidak perlu diperiksa karena terlihat menyenangkan dan menguntungkan, jadi langsung ikuti langkah-langkahnya"],answer:0,explain:"Prinsip lama tapi berguna: kalau terdengar terlalu bagus untuk jadi benar, biasanya memang bukan kenyataan.",hint:"Curigai yang terlalu bagus, atau percaya karena menyenangkan?"},
{n:56,type:"tf",micro:"Verifikasi tetap relevan meski dari teman",q:"Benar atau Salah: Kalau sebuah info dibagikan oleh teman atau keluarga yang kamu percaya, itu otomatis menjamin infonya akurat.",answer:false,explain:"Sebaliknya, kepercayaan pada orangnya berbeda dari akurasi informasinya. Orang baik pun bisa tanpa sadar meneruskan info yang salah karena belum sempat memeriksanya.",hint:"Tetap perlu diperiksa meski dari orang tepercaya, atau otomatis akurat?"},
{n:57,type:"mcq",micro:"Mengenali bot/akun otomatis",q:"Tanda sebuah akun mungkin bot (otomatis, bukan manusia asli) & bukan sumber tepercaya:",options:["Punya riwayat aktivitas bertahun-tahun yang wajar dan beragam, dengan interaksi yang alami bersama banyak orang","Memposting dalam jumlah sangat besar & cepat, jarang berinteraksi wajar, sering menyebarkan konten yang sama berulang","Memposting sesekali dengan gaya personal yang konsisten, membalas komentar orang lain, dan punya cerita pribadi"],answer:1,explain:"Pola posting yang sangat mekanis & masif (bukan seperti manusia biasa) adalah tanda umum akun otomatis yang dipakai menyebar info massal.",hint:"Posting masif & mekanis, atau aktivitas wajar bertahun-tahun?"},
{n:58,type:"mcq",micro:"Mengecek klaim lokal (sekolah/komunitas)",q:"Kabar yang beredar di grup kelas/komunitas ('sekolah akan diliburkan besok!') sebaiknya diverifikasi lewat...",options:["Ikut menyebarkannya dulu ke teman-teman lain, baru dicek nanti kalau ternyata ada yang meragukan kebenarannya","Percaya saja karena banyak orang membicarakannya di grup, sehingga benar dan tak perlu diperiksa lagi","Sumber resmi (pengumuman resmi sekolah, wali kelas, kanal resmi), bukan hanya rantai pesan grup"],answer:2,explain:"Kabar lokal pun rawan berubah saat diteruskan. Sumber resmi tetap jadi rujukan paling dapat dipercaya.",hint:"Cek sumber resmi, atau sebar dulu / percaya karena ramai?"},
{n:59,type:"mcq",micro:"Kapan cukup yakin membagikan",q:"Kamu bisa merasa cukup yakin membagikan sebuah info ketika...",options:["Sudah dicek ke lebih dari satu sumber tepercaya independen & sesuai dengan fakta yang bisa diverifikasi","Info itu sudah dibagikan banyak orang lain, sehingga makin banyak yang membagikan makin benar","Info itu terasa benar secara naluri atau perasaan, sehingga tidak perlu dicek ke sumber lain yang tepercaya"],answer:0,explain:"Verifikasi silang ke sumber independen adalah standar yang jauh lebih kuat daripada 'terasa benar' atau 'banyak yang bagikan'.",hint:"Terverifikasi silang, atau terasa benar / sudah viral?"},
{n:60,type:"open",micro:"Verifikasi sebuah klaim langkah demi langkah",q:"Pilih satu klaim yang pernah kamu lihat viral (atau buat contoh yang masuk akal). Tulis proses verifikasi langkah demi langkah yang AKAN kamu lakukan: (a) klaimnya apa, (b) reaksi emosional awalmu & kenapa kamu perlu jeda, (c) 3 langkah pengecekan konkret (sumber lain, tanggal, siapa penulis/asalnya), (d) kesimpulan sementara & tingkat keyakinanmu (tinggi/sedang/rendah) beserta alasannya.",explain:"Jawaban baik: klaim yang jelas & spesifik, kejujuran mengenali reaksi emosional & kenapa itu jadi alasan untuk jeda (bukan mengabaikan perasaan tapi menyadarinya), 3 langkah pengecekan yang konkret & relevan dengan jenis klaim tersebut, & kesimpulan dengan tingkat keyakinan yang beralasan (bukan sekadar 'aku percaya/tidak percaya').",hint:"Langkah pengecekan (c) harus spesifik untuk JENIS klaim itu, klaim kesehatan dicek ke BPOM/lembaga kesehatan, bukan langkah generik yang sama untuk semua jenis klaim.",sample:"(a) Klaim: 'Sebuah pesan viral mengklaim sebuah merek makanan terkenal memakai bahan berbahaya & sudah terbukti membuat banyak orang sakit, disertai foto kemasan produk & tulisan besar PERINGATAN.' (b) Reaksi emosional: aku langsung merasa khawatir & marah karena menyangkut kesehatan & produk yang sering kubeli; karena reaksinya kuat, aku sadar ini saat yang tepat untuk berhenti sejenak sebelum membagikannya ke keluarga, supaya tidak menyebarkan kepanikan yang mungkin tidak berdasar. (c) Langkah pengecekan: (1) Aku cari nama merek + 'bahan berbahaya' + 'cek fakta' di mesin pencari, untuk melihat apakah organisasi pemeriksa fakta atau media besar sudah membahasnya. (2) Aku cek apakah ada pernyataan resmi dari BPOM (badan pengawas obat & makanan) atau lembaga berwenang terkait klaim ini. (3) Aku periksa apakah foto kemasan di pesan itu memang produk & tanggal produksi terbaru, atau produk lama/berbeda yang dipakai untuk konteks yang salah, & apakah pesan yang sama pernah beredar sebelumnya dengan merek lain (pola pesan berantai yang didaur ulang). (d) Kesimpulan sementara: tingkat keyakinanku RENDAH terhadap klaim itu sampai aku menemukan konfirmasi dari BPOM atau media tepercaya, karena pesan ini punya banyak ciri khas hoaks (foto tanpa sumber jelas, menyebar lewat pesan berantai, memicu ketakutan kuat, tanpa rujukan resmi). Aku tidak akan membagikannya sampai menemukan sumber resmi yang mengonfirmasi atau membantahnya, & kalau ternyata terbukti hoaks, aku akan membagikan koreksinya alih-alih."},
{n:61,type:"mcq",micro:"Ruang gema & hoaks",q:"'Ruang gema' (echo chamber) membuat seseorang lebih rentan percaya hoaks karena...",options:["Ruang gema membuat orang lebih kritis secara otomatis, karena ia terbiasa membandingkan banyak pendapat dari sekitarnya","Ia hanya melihat sudut pandang yang sama berulang-ulang, sehingga info yang sesuai pandangan itu terasa 'pasti benar' tanpa pernah ditantang","Ia mendengar terlalu banyak sudut pandang berbeda, sehingga akhirnya sulit memutuskan mana yang benar"],answer:1,explain:"Ketika semua sumber di sekitarmu bilang hal yang sama, rasanya seperti konsensus, padahal itu bisa jadi hanya karena kamu dikelilingi pandangan yang seragam.",hint:"Hanya melihat sudut sama berulang, atau mendengar banyak sudut pandang?"},
{n:62,type:"mcq",micro:"Mengoreksi tanpa mempermalukan",q:"Kalau temanmu membagikan hoaks, cara mengoreksi yang efektif & baik:",options:["Sindir dia di kolom komentar publik supaya kapok dan orang lain tahu bahwa dia keliru menyebarkan hoaks","Diamkan saja karena tidak enak menegur teman, dan biarkan hoaksnya menyebar ke orang yang percaya","Sampaikan secara pribadi dengan sopan, sertakan sumber yang bisa diperiksa, tanpa mempermalukannya di depan umum"],answer:2,explain:"Koreksi yang mempermalukan sering membuat orang defensif & malah bertahan pada info salah. Pendekatan pribadi & hormat lebih efektif.",hint:"Sampaikan pribadi & sopan dengan sumber, atau sindir publik / diamkan?"},
{n:63,type:"mcq",micro:"Efek backfire (bumerang)",q:"'Efek bumerang' dalam koreksi hoaks terjadi ketika...",options:["Koreksi yang disampaikan dengan cara menyerang/merendahkan justru membuat orang makin kuat berpegang pada keyakinan salahnya","Koreksi langsung berhasil mengubah pikiran orang, tidak peduli bagaimana cara menyampaikannya kepada dia","Orang senang dikoreksi dengan cara apa saja, sehingga nada bicara dan pilihan kata tidak perlu dipikirkan"],answer:0,explain:"Cara menyampaikan koreksi memengaruhi hasilnya. Sikap menyerang bisa membuat orang defensif, bukan terbuka pada fakta baru.",hint:"Koreksi menyerang bisa memperkuat keyakinan salah, atau selalu langsung berhasil?"},
{n:64,type:"tf",micro:"Meminta maaf setelah membagikan hoaks tidak apa-apa",q:"Benar atau Salah: Kalau kamu terlanjur membagikan info yang ternyata salah, mengakui & mengoreksinya secara terbuka adalah sikap yang bertanggung jawab, bukan sesuatu yang memalukan.",answer:true,explain:"Semua orang bisa tertipu. Yang penting responsnya: mengakui & mengoreksi menunjukkan integritas, bukan kelemahan.",hint:"Bertanggung jawab & bukan memalukan, atau harus disembunyikan?"},
{n:65,type:"mcq",micro:"Tanggung jawab sebelum membagikan",q:"Membagikan info yang belum diverifikasi ke banyak orang (grup keluarga, kelas) membawa tanggung jawab karena...",options:["Hanya pembuat aslinya yang bertanggung jawab atas dampaknya, bukan yang membagikan","Kamu ikut menyebarkan dampaknya, baik atau buruk, ke orang-orang yang mempercayaimu","Membagikan tidak membawa tanggung jawab, sebab kamu hanya meneruskan dan bukan yang membuat kabarnya"],answer:1,explain:"Setiap orang dalam rantai penyebaran ikut berkontribusi pada dampaknya, terutama pada orang yang mempercayai penilaian kita.",hint:"Ikut bertanggung jawab atas dampak, atau tak ada tanggung jawab sama sekali?"},
{n:66,type:"mcq",micro:"Menghadapi ketidakpastian",q:"Kalau setelah verifikasi kamu masih tidak yakin apakah sebuah klaim benar atau salah, sikap yang matang:",options:["Bagikan saja sambil bilang 'katanya sih...' supaya kalau salah kamu tidak ikut disalahkan oleh orang yang membaca","Anggap saja benar karena sudah berusaha mencari, sehingga tak perlu menahan diri sebelum membagikannya","Tahan diri untuk tidak membagikan sampai lebih yakin, & katakan dengan jujur 'aku belum yakin' bila ditanya"],answer:2,explain:"Ketidakpastian adalah jawaban yang sah. Lebih baik jujur belum yakin daripada menyebarkan sesuatu yang belum terverifikasi sebagai 'kemungkinan benar'.",hint:"Tahan & jujur belum yakin, atau bagikan dengan embel-embel 'katanya'?"},
{n:67,type:"mcq",micro:"Media literasi sebagai keterampilan berkelanjutan",q:"Kenapa keterampilan memeriksa fakta perlu terus dilatih, bukan dipelajari sekali lalu selesai?",options:["Taktik menyesatkan terus berkembang (termasuk teknologi baru), jadi kewaspadaan & kebiasaan verifikasi perlu terus diperbarui","Setelah belajar sekali saja, seseorang otomatis kebal terhadap hoaks dan tidak perlu latihan atau pembaruan lagi di kemudian hari","Taktik hoaks tidak berubah dari dulu sampai sekarang, jadi cukup belajar sekali lalu semuanya aman"],answer:0,explain:"Sama seperti keamanan digital, literasi media adalah keterampilan yang perlu terus dipraktikkan seiring munculnya cara baru menyesatkan.",hint:"Perlu terus dilatih, atau otomatis kebal setelah belajar sekali?"},
{n:68,type:"tf",micro:"Skeptis bukan berarti tidak percaya apa pun",q:"Benar atau Salah: Bersikap kritis/skeptis terhadap info yang belum diverifikasi tidak sama dengan tidak pernah mempercayai apa pun; ada info yang memang layak dipercaya setelah diperiksa.",answer:true,explain:"Tujuannya bukan skeptisisme ekstrem yang meragukan segalanya, tapi kebiasaan memeriksa sebelum percaya penuh.",hint:"Skeptis proporsional, bukan meragukan segalanya, atau tidak pernah percaya apa pun?"},
{n:69,type:"mcq",micro:"Menyeimbangkan waktu verifikasi",q:"Tidak semua info butuh verifikasi mendalam yang sama. Cara memprioritaskan usaha verifikasi:",options:["Tidak perlu memverifikasi hal yang terlihat kecil atau sepele, karena yang kecil tidak punya dampak","Semakin besar dampaknya jika salah (kesehatan, keuangan, keputusan penting) & semakin luas akan dibagikan, semakin serius verifikasinya","Verifikasi semua hal dengan usaha yang sama persis, mulai dari lelucon sampai kabar kesehatan, tanpa membedakan dampaknya"],answer:1,explain:"Meme lucu ringan berbeda tingkat risikonya dengan klaim kesehatan yang akan kamu bagikan ke seluruh keluarga besar. Sesuaikan usaha dengan dampaknya.",hint:"Sesuaikan usaha dengan dampak & jangkauan, atau samakan semua / abaikan yang kecil?"},
{n:70,type:"tf",micro:"Literasi media melindungi orang lain juga",q:"Benar atau Salah: Kebiasaan memeriksa fakta sebelum membagikan tidak hanya melindungi dirimu, tapi juga orang-orang di sekitarmu yang mempercayai apa yang kamu bagikan.",answer:true,explain:"Setiap orang yang berhenti menyebarkan info salah memutus satu mata rantai penyebaran, melindungi lingkaran orang di sekitarnya.",hint:"Melindungi diri & orang lain, atau hanya diri sendiri?"},
{n:71,type:"mcq",micro:"Menghadapi orang yang sulit menerima koreksi",q:"Kalau seseorang tetap bersikeras pada info yang sudah jelas terbukti salah meski sudah diberi bukti, sikap yang bijak:",options:["Terus mendesak dan mengulang bukti berkali-kali sampai mereka mengaku salah, karena kamu harus memenangkan perdebatan itu","Menyerah lalu ikut menyebarkan info itu juga demi menghindari konflik, supaya suasana tetap damai dan orang senang","Sampaikan buktimu dengan tenang sekali, lalu terima bahwa kamu tidak bisa memaksa orang berubah pikiran; jangan sampai berdebat tanpa henti"],answer:2,explain:"Kamu bertanggung jawab menyampaikan dengan baik, bukan memaksa hasil. Berdebat berkepanjangan sering tidak produktif.",hint:"Sampaikan tenang lalu terima batasnya, atau memaksa terus / ikut menyebar?"},
{n:72,type:"mcq",micro:"Hoaks & polarisasi",q:"Hoaks yang menargetkan kelompok tertentu (etnis, agama, kelompok politik) berdampak lebih serius karena...",options:["Bisa memperkuat prasangka & permusuhan nyata antar kelompok, bukan hanya menyesatkan soal fakta","Dampaknya tidak lebih serius daripada hoaks jenis lain, sebab semua hoaks berpengaruh sama bagi masyarakat","Mudah dikenali oleh orang banyak sehingga tidak berbahaya, dan hampir tak ada yang percaya padanya"],answer:0,explain:"Hoaks semacam ini bisa memicu konflik sosial nyata, jadi memeriksa & tidak menyebarkannya adalah tanggung jawab yang lebih besar.",hint:"Memperkuat prasangka & konflik, atau tak ada dampak lebih / mudah dikenali?"},
{n:73,type:"mcq",micro:"Kebiasaan baik jangka panjang",q:"Kebiasaan literasi media yang baik untuk dibangun sejak sekarang:",options:["Membagikan sebanyak mungkin kabar yang kamu temui tanpa menyaring, supaya orang lain cepat mendapat informasi","Jeda sebelum bagikan, cek sumber lain, & terbuka mengoreksi diri sendiri saat keliru","Percaya yang pertama kamu lihat, karena yang pertama muncul paling asli"],answer:1,explain:"Ketiga kebiasaan ini (jeda, verifikasi, terbuka dikoreksi) adalah fondasi yang akan terus berguna seiring bertambahnya jumlah info yang kita temui.",hint:"Jeda + verifikasi + terbuka dikoreksi, atau percaya cepat / bagikan tanpa saring?"},
{n:74,type:"mcq",micro:"Algoritma & konten yang kita lihat",q:"Memahami bahwa platform sering menampilkan konten yang 'mendapat banyak reaksi' (bukan yang paling akurat) membantu kita...",options:["Percaya bahwa yang paling sering muncul di beranda yang paling benar dan akurat bagi banyak orang","Tidak berpengaruh pada cara kita menilai info, karena apa yang muncul di beranda tidak berhubungan dengan reaksi orang","Sadar bahwa yang sering muncul di beranda kita belum tentu yang paling benar, hanya yang paling memancing reaksi"],answer:2,explain:"Sistem rekomendasi sering mengutamakan yang memicu interaksi (emosi, perdebatan), bukan akurasi. Kesadaran ini penting.",hint:"Yang sering muncul belum tentu paling benar, atau pasti paling benar?"},
{n:75,type:"order",micro:"Menanggapi hoaks di grup keluarga",q:"Urutkan langkah menanggapi hoaks yang dibagikan di grup keluarga.",items:["Verifikasi klaimnya sendiri lewat sumber tepercaya","Hubungi pengirim secara pribadi (bukan langsung di grup) untuk menyampaikan temuan dengan sopan","Bila perlu & pengirim setuju, bagikan koreksi di grup dengan nada baik, bukan menyalahkan","Tetap hormati hubungan keluarga meski ada perbedaan pandangan"],answer:[0,1,2,3],explain:"Verifikasi dulu → sampaikan pribadi dengan sopan → koreksi di grup bila perlu tanpa menyalahkan → jaga hubungan baik. Pendekatan pribadi dulu menjaga martabat semua pihak.",hint:"Menghubungi pengirim secara pribadi sebelum atau sesudah verifikasi klaimnya?"},
{n:76,type:"tf",micro:"Verifikasi bukan tanda tidak percaya orang",q:"Benar atau Salah: Memeriksa fakta sebuah info yang dibagikan seseorang bukan berarti kamu tidak mempercayai atau meragukan orang itu secara pribadi.",answer:true,explain:"Memeriksa info adalah kebiasaan terhadap SEMUA info, bukan penilaian terhadap karakter orang yang membagikannya.",hint:"Bukan berarti meragukan orangnya, atau selalu tanda tidak percaya orang?"},
{n:77,type:"mcq",micro:"Menyikapi ketidaktahuan sendiri",q:"Kalau kamu tidak tahu apakah sebuah klaim di luar bidang yang kamu pahami itu benar (mis. klaim ilmiah rumit), sikap yang jujur:",options:["Akui belum tahu, cari penjelas dari sumber ahli/tepercaya, & jangan berpura-pura yakin","Berpura-pura paham dan ikut membagikan kesimpulannya, supaya terlihat pintar dan tidak ketinggalan dari teman","Menolak klaim di bidang yang tidak kamu pahami, karena yang rumit biasanya keliru"],answer:0,explain:"Mengakui keterbatasan pengetahuan sendiri & mencari sumber yang lebih paham adalah sikap rendah hati yang sehat, bukan kelemahan.",hint:"Akui belum tahu & cari sumber ahli, atau pura-pura paham / tolak semua?"},
{n:78,type:"mcq",micro:"Menyeimbangkan kewaspadaan & rasa ingin tahu",q:"Sikap yang sehat terhadap informasi baru:",options:["Menolak semua informasi baru karena mungkin hoaks, sehingga kamu aman dari kesalahan","Terbuka & ingin tahu, tapi dengan kebiasaan memeriksa sebelum sepenuhnya percaya, bukan menolak semua hal baru begitu saja","Menerima semua informasi baru tanpa saring, karena menolak sesuatu berarti kamu menutup diri dari pengetahuan baru"],answer:1,explain:"Terbuka + kritis adalah kombinasi yang sehat. Menutup diri dari info baru sama tidak sehatnya dengan menerima semuanya tanpa saring.",hint:"Terbuka & kritis, atau menerima semua / menolak semua?"},
{n:79,type:"mcq",micro:"Hoaks yang menargetkan ketakutan anak",q:"Hoaks yang sengaja dibuat untuk menakut-nakuti anak-anak (mis. cerita seram palsu yang beredar) perlu ditangani dengan...",options:["Dibiarkan saja begitu karena 'namanya juga anak-anak', dan nanti mereka akan lupa dengan sendirinya tanpa dijelaskan","Ditakut-takuti lebih jauh supaya mereka jera dan tidak berani lagi membagikan cerita-cerita seperti itu kepada temannya","Klarifikasi yang tenang & jelas dari orang dewasa tepercaya, bukan dibiarkan begitu saja atau ditertawakan tanpa penjelasan"],answer:2,explain:"Ketakutan yang dibangun dari hoaks tetap terasa nyata bagi yang mempercayainya. Penjelasan yang tenang & jelas membantu memulihkan rasa aman.",hint:"Klarifikasi tenang dari orang tepercaya, atau dibiarkan / ditakuti lebih jauh?"},
{n:80,type:"open",micro:"Menanggapi keluarga yang membagikan hoaks",q:"Bibimu membagikan sebuah artikel kesehatan yang setelah kamu cek ternyata hoaks (klaim tidak berdasar, situs tidak jelas, tidak ada di sumber resmi). Tulis: (a) bagaimana kamu akan memulai percakapan dengannya (kalimat pembuka), (b) bukti apa yang akan kamu sampaikan & bagaimana caranya, (c) bagaimana kamu tetap menjaga hubungan baik meski mengoreksi, (d) apa yang akan kamu lakukan kalau dia tetap tidak percaya setelah kamu jelaskan.",explain:"Jawaban baik: kalimat pembuka yang sopan & tidak menyalahkan, bukti konkret dari sumber tepercaya yang disampaikan secara pribadi, cara menjaga hubungan yang mengakui niat baik lawan bicara, & sikap yang matang saat koreksi tidak diterima (tidak memaksa, tapi juga tidak ikut menyebarkan info salah).",hint:"Bagian (a) sangat menentukan, kalimat pembuka yang menyalahkan langsung sering membuat orang defensif sebelum sempat mendengar buktimu.",sample:"(a) Kalimat pembuka: 'Bi, makasih ya udah share, aku jadi penasaran & coba cari tahu lebih lanjut soal ini. Boleh aku share yang kutemukan?' (bukan 'Bi, itu hoaks lho' yang terasa menyalahkan langsung). (b) Bukti yang disampaikan: aku akan menunjukkan hasil pencarianku, misalnya tautan dari situs resmi BPOM atau organisasi kesehatan yang membantah klaim serupa, atau tautan dari situs pemeriksa fakta yang sudah membahas artikel yang sama persis; aku akan mengirimnya lewat pesan pribadi dulu, bukan membalas di grup keluarga besar, supaya tidak terasa mempermalukan di depan banyak orang. (c) Menjaga hubungan baik: aku akan mengakui bahwa niatnya baik ('aku tahu Bibi share ini karena peduli sama kesehatan keluarga, itu bagus banget'), fokus pada info-nya yang keliru, bukan mengatakan Bibi bodoh atau ceroboh, & tetap mengucapkan terima kasih atas perhatiannya. (d) Kalau dia tetap tidak percaya: aku tidak akan memaksa atau berdebat berkepanjangan; aku akan bilang 'Oke Bi, aku sudah sampaikan yang kutemukan ya, kalau ada info baru nanti aku kabari lagi' & membiarkan itu, sambil tetap tidak ikut menyebarkan artikel itu sendiri & kalau perlu, memberi tahu anggota keluarga lain secara terpisah dengan cara yang sama baiknya, supaya mereka juga tahu ada sumber yang membantahnya."},
{n:81,type:"mcq",micro:"Skenario: pesan berantai tentang bahaya makanan",q:"Pesan berantai mengklaim sebuah bahan makanan umum 'menyebabkan kanker', dibagikan tanpa sumber, & meminta 'sebarkan agar semua tahu'. Langkah tepat:",options:["Cari klaim ini di situs resmi kesehatan atau organisasi pemeriksa fakta sebelum memutuskan percaya atau membagikan","Sebarkan segera karena menyangkut kesehatan orang banyak, tanpa perlu mencari sumbernya terlebih dahulu","Abaikan sepenuhnya tanpa memeriksa, karena pesan berantai itu bohong dan tidak perlu dibaca lagi"],answer:0,explain:"Klaim kesehatan besar tanpa sumber butuh verifikasi ke lembaga berwenang sebelum disebarkan lebih jauh, agar tidak menimbulkan ketakutan yang tidak berdasar.",hint:"Verifikasi ke sumber resmi dulu, atau sebar segera / abaikan tanpa cek?"},
{n:82,type:"mcq",micro:"Skenario: video yang terlihat mengejutkan",q:"Sebuah video pendek yang sangat mengejutkan beredar tanpa keterangan jelas kapan & di mana diambil. Langkah verifikasi:",options:["Bagikan dengan keterangan 'katanya ini kejadian kemarin' supaya orang lain ikut waspada dan tahu dengan cepat","Cari apakah video itu (atau bagian darinya) pernah muncul sebelumnya dengan konteks berbeda, & cari liputan resmi tentang kejadian itu","Percaya begitu saja karena video tidak bisa bohong, sehingga tidak perlu mencari tahu kapan dan di mana kejadiannya"],answer:1,explain:"Video bisa dilepas dari konteks asli atau lama. Verifikasi asal & konteksnya sebelum menyimpulkan apa & kapan itu terjadi.",hint:"Cari konteks & liputan asli, atau percaya video / bagikan tebakan?"},
{n:83,type:"mcq",micro:"Skenario: klaim tentang sekolah sendiri",q:"Beredar kabar di media sosial bahwa 'sekolahmu akan ditutup permanen'. Langkah pertama yang tepat:",options:["Langsung percaya dan memberi tahu semua teman supaya mereka tidak datang ke sekolah yang sudah tutup itu esok hari","Buat unggahan sendiri yang membantah kabar itu tanpa memastikan dulu apakah bantahanmu sendiri benar atau salah","Tanyakan langsung ke pihak sekolah (guru, kepala sekolah, kanal resmi) sebelum percaya atau menyebarkan kepanikan"],answer:2,explain:"Untuk info yang menyangkut institusi tempatmu berada, sumber resmi & langsung adalah rujukan paling akurat & cepat.",hint:"Tanya pihak resmi langsung, atau percaya / membantah tanpa pastikan?"},
{n:84,type:"mcq",micro:"Skenario: teman percaya teori konspirasi",q:"Temanmu mulai percaya sebuah teori konspirasi & menolak semua bukti yang bertentangan. Pendekatan yang lebih mungkin membantu:",options:["Ajukan pertanyaan yang mengajaknya berpikir sendiri ('menurutmu apa yang akan membuktikan ini salah?') daripada langsung menyerang keyakinannya","Menertawakan dan mengucilkannya di depan teman-teman lain supaya ia sadar bahwa pendapatnya aneh dan tidak diterima","Berdebat keras terus-menerus sampai dia mengaku kalah, sebab menang dalam perdebatan akan membuatnya mengubah keyakinannya"],answer:0,explain:"Pertanyaan yang mengajak berpikir sering lebih efektif daripada konfrontasi langsung, yang cenderung membuat orang makin bertahan.",hint:"Ajak berpikir dengan pertanyaan, atau menyerang / mengucilkan?"},
{n:85,type:"tf",micro:"Verifikasi adalah keterampilan yang bisa diajarkan",q:"Benar atau Salah: Kemampuan memeriksa fakta bisa diajarkan & dilatih, bukan bakat bawaan yang hanya dimiliki sebagian orang.",answer:true,explain:"Seperti keterampilan lain, kebiasaan verifikasi tumbuh lewat latihan & praktik berulang, bisa dipelajari siapa saja di usia berapa pun.",hint:"Bisa diajarkan & dilatih, atau bakat bawaan terbatas?"},
{n:86,type:"mcq",micro:"Skenario: pesan yang membuatmu ingin membagikan segera",q:"Kamu membaca sesuatu yang membuatmu ingin langsung membagikan ke semua orang saat itu juga. Sinyal yang perlu kamu kenali:",options:["Makin cepat dibagikan makin baik, karena kabar yang lambat disebarkan kehilangan nilai dan manfaatnya","Dorongan kuat & segera untuk berbagi adalah tanda untuk melambat, bukan mempercepat, karena itu sering tanda manipulasi emosi","Dorongan yang kuat berarti info itu penting dan benar, sehingga tidak perlu dicek lagi sebelum disebarkan ke orang lain"],answer:1,explain:"Dorongan emosional yang kuat adalah sinyal untuk jeda, sesuai pola yang sudah dipelajari: hoaks sering dirancang memicu reaksi cepat itu.",hint:"Tanda untuk melambat, atau tanda pasti penting & benar?"},
{n:87,type:"mcq",micro:"Skenario: proyek sekolah butuh sumber",q:"Untuk tugas sekolah, kamu menemukan info menarik di sebuah blog pribadi tanpa rujukan jelas. Langkah yang tepat:",options:["Pakai langsung saja karena sudah menemukan info yang dibutuhkan, dan blog itu terlihat meyakinkan serta rapi isinya","Tulis ulang dengan kata-katamu sendiri tanpa menyebut sumber, supaya tugasmu terlihat asli dan tanpa rujukan","Cari sumber yang lebih kredibel (buku, situs resmi, jurnal) yang menyebutkan hal serupa sebelum memakainya di tugas"],answer:2,explain:"Untuk keperluan akademik, sumber perlu lebih kredibel & bisa dirujuk. Blog pribadi tanpa rujukan bukan sumber yang kuat untuk tugas.",hint:"Cari sumber lebih kredibel, atau pakai langsung / tanpa sumber?"},
{n:88,type:"mcq",micro:"Skenario: informasi darurat yang mendesak",q:"Saat ada situasi darurat nyata (bencana, dll) & informasi berubah cepat, cara tetap waspada tanpa ikut menyebarkan kepanikan:",options:["Ikuti sumber resmi (BNPB, pemerintah setempat, media besar tepercaya) untuk update, & hindari menyebarkan info belum terkonfirmasi meski terasa mendesak","Sebarkan semua yang kamu dengar dari mana saja agar orang lain bisa bersiap-siap sedini mungkin, termasuk kabar yang belum jelas sumber dan kebenarannya","Diam total dan tidak mencari info, karena dalam situasi darurat sebaiknya kamu tidak membaca kabar dari sumber mana pun"],answer:0,explain:"Saat darurat, info salah bisa sangat berbahaya (orang panik ke arah yang salah). Sumber resmi tetap jadi rujukan paling aman meski situasinya cepat berubah.",hint:"Ikuti sumber resmi, atau sebar semua / diam total?"},
{n:89,type:"mcq",micro:"Skenario: membantu keluarga yang kurang paham teknologi",q:"Kakek/nenekmu sering membagikan hoaks tanpa sadar karena kurang terbiasa dengan internet. Cara membantu yang menghormati:",options:["Menyita HP mereka agar tak bisa membagikan lagi, karena itu cara tercepat menghentikan penyebaran hoaksnya","Ajarkan pelan-pelan dengan contoh konkret & sabar, tanpa merendahkan, karena mereka tumbuh di era yang berbeda","Menertawakan kebiasaan mereka di depan keluarga supaya mereka malu dan berhenti membagikan kabar yang belum jelas benarnya"],answer:1,explain:"Kesabaran & rasa hormat penting saat mengajarkan keterampilan baru pada generasi yang tumbuh dengan cara berbeda mengakses informasi.",hint:"Ajarkan sabar & hormat, atau menertawakan / mengambil alih paksa?"},
{n:90,type:"order",micro:"Proyek: kampanye literasi media mini",q:"Urutkan langkah membuat 'kampanye kecil' literasi media untuk kelas/keluargamu.",items:["Kumpulkan 3-5 contoh hoaks umum yang beredar di lingkunganmu & analisis ciri-cirinya","Buat panduan sederhana (poster/pesan singkat) berisi cara mengenali & memeriksa fakta","Bagikan panduan itu ke kelas/keluarga dengan cara yang ramah, bukan menggurui","Kumpulkan umpan balik & perbaiki panduan berdasarkan pertanyaan yang muncul"],answer:[0,1,2,3],explain:"Kumpulkan contoh nyata → buat panduan → bagikan dengan ramah → perbaiki dari umpan balik. Contoh nyata membuat panduan lebih relevan & mudah dipahami.",hint:"Membuat panduan sebelum atau sesudah mengumpulkan contoh nyata?"},
{n:91,type:"mcq",micro:"Skenario: kamu salah menuduh sesuatu hoaks",q:"Kamu menyebut sebuah info sebagai hoaks di depan teman-teman, tapi ternyata setelah dicek ulang info itu benar. Sikap yang tepat:",options:["Diam saja dan berharap tak ada yang mengingat tuduhanmu, sebab mengakui kesalahan membuatmu terlihat lemah","Membela diri dengan mengatakan info itu 'mungkin masih hoaks' walau bukti sudah menunjukkan sebaliknya, supaya tidak malu","Akui kekeliruanmu secara terbuka ke orang yang sama yang mendengar tuduhanmu, & jelaskan apa yang membuatmu salah menilai"],answer:2,explain:"Prinsip yang sama berlaku dua arah: mengakui kesalahan (termasuk salah menuduh hoaks) menunjukkan integritas & kejujuran intelektual.",hint:"Akui secara terbuka, atau diam / membela diri tanpa dasar?"},
{n:92,type:"tf",micro:"Literasi media adalah tanggung jawab bersama",q:"Benar atau Salah: Melawan penyebaran hoaks adalah tanggung jawab bersama, setiap orang yang berhenti sebelum membagikan info yang belum terverifikasi ikut berkontribusi.",answer:true,explain:"Tidak ada satu pihak yang bisa sendirian menghentikan penyebaran hoaks; kebiasaan individu yang menyebar luas membuat perbedaan besar.",hint:"Tanggung jawab bersama tiap individu, atau hanya tanggung jawab pihak tertentu?"},
{n:93,type:"mcq",micro:"Skenario: klaim yang menguntungkan idolamu",q:"Ada klaim positif tentang idola/tokoh yang kamu kagumi, tapi sumbernya meragukan. Sikap yang jujur pada diri sendiri:",options:["Tetap periksa klaimnya dengan standar yang sama, meski itu tentang seseorang yang kamu sukai","Langsung percaya begitu saja karena klaimnya tentang idola yang kamu sukai, jadi tidak perlu diperiksa sumbernya lagi","Bagikan tanpa cek karena membuat idolamu terlihat baik di mata orang"],answer:0,explain:"Bias konfirmasi bekerja paling kuat justru pada info yang menguntungkan orang/hal yang kita sukai. Standar verifikasi seharusnya sama untuk semua klaim.",hint:"Periksa dengan standar sama, atau langsung percaya karena suka?"},
{n:94,type:"mcq",micro:"Skenario: perdebatan di kelas soal sebuah klaim",q:"Diskusi kelas terpecah soal kebenaran sebuah klaim yang beredar. Cara memfasilitasi yang produktif:",options:["Hindari topik itu agar tidak ribut dan suasana kelas tetap tenang, walau pertanyaannya tidak terjawab","Ajak semua mencari sumber bersama-sama secara langsung (bukan hanya berdebat pendapat) & bandingkan temuannya","Biarkan yang paling keras suaranya menang, karena orang yang paling bersemangat bicara adalah yang paling tahu"],answer:1,explain:"Mengalihkan perdebatan pendapat ke pencarian bukti bersama mengubah suasana dari 'siapa benar' jadi 'apa faktanya', yang lebih produktif.",hint:"Cari sumber bersama & bandingkan, atau biarkan yang keras menang / hindari topik?"},
{n:95,type:"tf",micro:"Kemampuan ini makin penting seiring waktu",q:"Benar atau Salah: Seiring makin banyak informasi & makin canggihnya teknologi pembuat konten palsu, kemampuan memeriksa fakta akan makin penting di masa depan, bukan makin tidak relevan.",answer:true,explain:"Volume informasi terus bertambah & alat pembuat konten menyesatkan makin canggih, membuat keterampilan ini makin krusial, bukan usang.",hint:"Makin penting ke depan, atau makin tidak relevan?"},
{n:96,type:"mcq",micro:"Skenario: menyusun pesan koreksi yang baik",q:"Kamu ingin mengoreksi sebuah hoaks di grup besar. Struktur pesan yang efektif:",options:["Ulangi hoaksnya secara rinci dulu supaya semua paham apa yang salah, baru kemudian membantahnya dengan satu kalimat saja di akhir","Hanya menulis 'ini hoaks' tanpa penjelasan atau sumber, karena orang lain langsung percaya ucapanmu","Nyatakan fakta yang benar dengan jelas di awal (bukan mengulang mitos yang salah dulu), sertakan sumber, & sampaikan dengan nada membantu"],answer:2,explain:"Mengulang mitos yang salah (meski untuk membantahnya) bisa memperkuatnya di ingatan orang. Mulai dengan fakta yang benar lebih efektif secara psikologis.",hint:"Mulai dengan fakta benar + sumber + nada membantu, atau ulangi mitos dulu / tanpa penjelasan?"},
{n:97,type:"mcq",micro:"Menilai pemahaman diri",q:"Tanda kamu sudah cukup mahir mengenali & memeriksa hoaks:",options:["Kamu terbiasa jeda sebelum membagikan, tahu langkah verifikasi dasar, mengenali pola manipulasi umum, & terbuka mengoreksi diri sendiri","Kamu hafal daftar situs hoaks dengan sangat baik tetapi tetap membagikan kabar mengejutkan tanpa berpikir dan tanpa memeriksa lebih dulu","Kamu berhenti membaca berita supaya tidak tertipu hoaks, dan menyuruh teman-temanmu melakukan hal yang sama"],answer:0,explain:"Kemahiran sejati terlihat dari kebiasaan nyata (jeda, verifikasi, kenali pola, terbuka koreksi), bukan sekadar tahu daftar atau menghindari berita sepenuhnya.",hint:"Kebiasaan nyata & terbuka koreksi, atau hafal daftar tanpa berubah / hindari berita?"},
{n:98,type:"mcq",micro:"Hoaks & masyarakat sehat",q:"Masyarakat dengan banyak warga yang terbiasa memeriksa fakta cenderung...",options:["Tidak berpengaruh pada kualitas keputusan bersama, karena keputusan masyarakat tidak bergantung pada informasi warga","Lebih tahan terhadap manipulasi & bisa membuat keputusan bersama yang lebih baik berdasarkan fakta","Menjadi tempat membosankan tanpa informasi baru, karena warganya terlalu sibuk memeriksa dan tidak sempat berbagi kabar"],answer:1,explain:"Literasi media yang luas adalah fondasi masyarakat yang bisa berdiskusi & memutuskan berdasarkan fakta bersama, bukan mudah dipecah belah info palsu.",hint:"Lebih tahan manipulasi & keputusan lebih baik, atau tak berpengaruh?"},
{n:99,type:"mcq",micro:"Inti keterampilan",q:"Inti dari 'mengenali hoaks & memeriksa fakta':",options:["Percaya semua yang terlihat meyakinkan, membagikan secepat mungkin saat merasa emosi, dan menganggap pembuat kabar yang bertanggung jawab atas dampaknya","Menolak semua informasi baru, tidak mempercayai sumber mana pun, dan tidak memeriksa apakah kabar itu benar","Kenali tanda & pola konten menyesatkan, jeda sebelum percaya/berbagi terutama saat emosi kuat, verifikasi ke sumber independen, & bertanggung jawab atas apa yang kamu sebarkan"],answer:2,explain:"Kenali pola + jeda emosi + verifikasi + tanggung jawab. Kombinasi ini membuat kita jadi penyaring yang baik, bukan penyebar otomatis.",hint:"Kenali pola + jeda + verifikasi + tanggung jawab, atau percaya semua / tolak semua?"},
{n:100,type:"open",micro:"Kapstone: panduan pribadi memeriksa fakta",q:"Buat 'panduan pribadi memeriksa fakta' untuk dipakai mulai sekarang. Sertakan: (a) 3-5 tanda peringatan yang akan membuatmu waspada pada sebuah info, (b) langkah verifikasi berurutan yang akan kamu ikuti, (c) aturan pribadi soal kapan kamu akan/tidak akan membagikan sesuatu, (d) rencana konkret bagaimana kamu akan mengoreksi diri sendiri atau orang lain dengan baik, (e) satu cara kamu akan terus melatih keterampilan ini ke depan.",explain:"Jawaban baik: 3-5 tanda peringatan yang spesifik & mencakup berbagai aspek (bahasa, sumber, emosi, besarnya klaim, kesendirian sumber), langkah verifikasi berurutan yang konkret & bisa diikuti, aturan pribadi yang jelas & realistis (termasuk membedakan tingkat kehati-hatian sesuai dampak), rencana koreksi yang matang untuk diri sendiri & orang lain, & cara berlatih berkelanjutan yang benar-benar bisa dilakukan.",hint:"Bagian (e) sering diisi generik ('akan lebih waspada'), buat jadi kebiasaan konkret yang bisa benar-benar dijalankan & diperiksa.",sample:"(a) Tanda peringatan: (1) Judul/pesan sangat berlebihan atau mendesak untuk segera dibagikan. (2) Tidak menyebut sumber, penulis, atau tanggal yang jelas. (3) Membuatku merasa sangat emosional (marah/takut/kaget) sebelum sempat berpikir. (4) Klaim besar (menyembuhkan segala penyakit, hancur total, dll) tanpa bukti sepadan. (5) Hanya satu sumber yang tidak dikenal yang menyebutkannya, sumber lain diam. (b) Langkah verifikasi: (1) Jeda sejenak kalau aku merasa sangat emosional. (2) Cari klaim intinya di mesin pencari, tambahkan kata 'cek fakta' atau 'benarkah'. (3) Cek apakah media/lembaga tepercaya lain melaporkan hal serupa. (4) Untuk klaim kesehatan/keuangan/keselamatan, cek ke lembaga resmi terkait. (5) Kalau ada gambar/video, cek konteks aslinya (kapan, di mana, apakah pernah dipakai untuk hal lain). (c) Aturan pribadi: aku hanya akan membagikan sesuatu setelah minimal satu dari langkah verifikasi di atas kulakukan dengan hasil meyakinkan; untuk hal yang menyangkut kesehatan/keselamatan orang banyak, aku akan lebih ketat & menunggu sumber resmi sebelum membagikan, meski itu berarti aku 'kalah cepat' dari yang lain. (d) Rencana mengoreksi: kalau menemukan diriku sendiri sudah terlanjur membagikan info salah, aku akan mengakuinya secara terbuka & mengoreksi ke orang yang sama; kalau melihat orang lain (terutama yang kukenal) membagikan hoaks, aku akan menghubungi secara pribadi dulu dengan sopan sebelum mempertimbangkan koreksi publik, & selalu menyertakan sumber yang bisa mereka periksa sendiri. (e) Melatih terus: setiap kali aku menemukan klaim viral yang menarik perhatianku, aku akan menjadikannya 'latihan verifikasi' meski aku tidak berencana membagikannya, supaya kebiasaan ini makin otomatis; aku juga akan sesekali membaca tulisan dari organisasi pemeriksa fakta untuk melihat pola-pola hoaks terbaru yang sedang beredar."},
];
